-- First, nullify tile references in polen_entries to avoid FK constraint violations
UPDATE polen_entries SET tile_id = NULL WHERE tile_id IS NOT NULL;

-- Also nullify references in journal_cycles
UPDATE journal_cycles SET current_tile_id = NULL WHERE current_tile_id IS NOT NULL;

-- Also nullify references in tolerance_expansion_events
UPDATE tolerance_expansion_events SET trigger_tile_id = NULL WHERE trigger_tile_id IS NOT NULL;

-- Also nullify references in events table
DELETE FROM events WHERE tile_id IS NOT NULL;

-- Now clear existing partial tile data
DELETE FROM tiles;

